param([string]$ResultRoot="",[string]$OutputPath="")
$ErrorActionPreference="Stop"
$repo=(Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path
$root=if($ResultRoot){(Resolve-Path $ResultRoot).Path}else{Join-Path $repo "experiment\results\experiment-1-56"}
$out=if($OutputPath){$OutputPath}else{Join-Path $root "aggregate-summary.json"}
$ids=@("C400-S1","C400-S2","C400-R2","C400-R3","C500-S1","C500-S2","C600-S1","C600-R2","C600-R3","C700-S1")
$excluded=@{"C400-S1"="PORT_MAPPING_HARNESS_FAILURE";"C500-S1"="POOL_CONTRACT_HARNESS_FAILURE"}
function Median($v){$a=@($v|?{$null-ne$_}|sort);if($a.Count-eq 0){return $null};return $a[[Math]::Floor(($a.Count-1)/2)]}
$rows=@()
foreach($id in $ids){$d=Join-Path $root $id;if(-not(Test-Path "$d/load-summary.json")){continue};$cfg=Get-Content "$d/run-config.json" -Raw|ConvertFrom-Json;$s=(Get-Content "$d/load-summary.json" -Raw|ConvertFrom-Json).summary;$valid=((Get-Content "$d/validity.json" -Raw|ConvertFrom-Json).valid -and -not $excluded.ContainsKey($id));$reason=if($excluded.ContainsKey($id)){$excluded[$id]}else{$null};$h=$s.latencyByOutcome.HTTP_200_ACCEPTED;$completedPerLoadSecond=$s.throughputRequestsPerSecond;$acceptedPerLoadSecond=if($s.durationMs){$s.successfulRequests/($s.durationMs/1000)}else{$null};$active=@();$pending=@();$pendingNonzero=0;$numericSamples=0;if(Test-Path "$d/provider-metrics.jsonl"){foreach($line in Get-Content "$d/provider-metrics.jsonl"){try{$o=$line|ConvertFrom-Json;$ms=$o.payload.metrics;if($ms.Count-gt 0){$numericSamples++;foreach($m in $ms){if($m.name-match 'active.connections'){$active+=[double]$m.value};if($m.name-match 'pending.connections' -and $m.name-notmatch 'max.pending'){$pending+=[double]$m.value;if([double]$m.value-gt 0){$pendingNonzero++}}}}}catch{}}};$rows+=[ordered]@{runId=$id;capacity=$cfg.capacity;valid=$valid;invalidReason=$reason;successfulRequests=$s.successfulRequests;http200=$s.outcomeCounts.HTTP_200_ACCEPTED;http500=$s.outcomeCounts.HTTP_500_UNCONTROLLED;http503Admission=$s.outcomeCounts.HTTP_503_ADMISSION;http503Downstream=$s.outcomeCounts.HTTP_503_DOWNSTREAM;timeout=$s.outcomeCounts.CLIENT_TIMEOUT;connectionError=$s.outcomeCounts.CONNECTION_ERROR;completedPerLoadSecond=$completedPerLoadSecond;acceptedCompletionsPerLoadSecond=$acceptedPerLoadSecond;successRate=if($s.completedRequests){$s.successfulRequests/$s.completedRequests}else{0};allLatency=$s.latencyMs;http200Latency=$h;maxInFlight=$s.maxInFlight;providerActivePeak=if($active){($active|measure -Maximum).Maximum}else{$null};providerPendingPeak=if($pending){($pending|measure -Maximum).Maximum}else{$null};providerPendingNonzeroSamples=$pendingNonzero;providerNumericSamples=$numericSamples;providerTimelineStatus=if($numericSamples){"PASS"}else{"NOT_RECOVERABLE"}}}
$groups=[ordered]@{};foreach($c in @("C400","C500","C600","C700")){$r=@($rows|Where-Object {$_.capacity -eq $c -and $_.valid});$groups[$c]=[ordered]@{validRuns=$r.Count;median=[ordered]@{acceptedCompletionsPerLoadSecond=Median ($r|ForEach-Object {$_.acceptedCompletionsPerLoadSecond});completedPerLoadSecond=Median ($r|ForEach-Object {$_.completedPerLoadSecond});successRate=Median ($r|ForEach-Object {$_.successRate});http200P95=Median ($r|ForEach-Object {$_.http200Latency.p95});http200P99=Median ($r|ForEach-Object {$_.http200Latency.p99});allP95=Median ($r|ForEach-Object {$_.allLatency.p95});timeout=Median ($r|ForEach-Object {$_.timeout});connectionError=Median ($r|ForEach-Object {$_.connectionError});providerActivePeak=Median ($r|ForEach-Object {$_.providerActivePeak});providerPendingPeak=Median ($r|ForEach-Object {$_.providerPendingPeak})};runs=$r}}
$result=[ordered]@{experiment="Exp156";metricSchemaVersion="exp155-evidence-repair-v1";generatedAt=[DateTime]::UtcNow.ToString("o");screeningIds=@("C400-S2","C500-S2","C600-S1","C700-S1");finalCandidateIds=@("C400-S2","C400-R2","C400-R3","C600-S1","C600-R2","C600-R3");excludedRuns=$excluded;runs=$rows;groups=$groups;decision="BEST_OBSERVED_STATIC_CAPACITY";bestObservedCapacity="C600";tokenStorageFollowup="NO";decisionBasis="C600 had the highest three-run median accepted HTTP 200 completion rate among final candidates; C700 screening was lower and showed no compensating resource or tail benefit."}
New-Item -ItemType Directory -Force -Path (Split-Path $out)|Out-Null;$result|ConvertTo-Json -Depth 50|Set-Content $out -Encoding UTF8;Write-Output "EXP156_SUMMARY_WRITTEN $out"
